typealias Pair<T> = (T, T)
let point: Pair<Int> = (3, 4)
print(point.0 + point.1)

extension Array where Element == Int {
    func total() -> Int { reduce(0, +) }
}
print([1, 2, 3].total())

struct Bag {
    let all: [Any] = [1, "hi", 2]
    subscript<T>(_: T.Type) -> [T] {
        all.compactMap { $0 as? T } }
}
print(Bag()[Int.self], Bag()[String.self])

